+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * Verifies, in a real (headless) browser, what the browserless suite cannot see:
+ * the address bar and how many backend queries a burst of keystrokes costs.
+ */
+@SpringBootTest(classes = Application.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    private static Locator nameInputLocator(Page page) {
+        return new TextFieldElement(page.locator("vaadin-text-field")).getInputLocator();
+    }
+
+    @Test
+    void typingDoesNotQueryOncePerKeystrokeAndUpdatesTheUrlWithoutNewHistoryEntries() {
+        Page page = getPage();
+        Locator nameInput = nameInputLocator(page);
+
+        int historyLengthBefore = ((Number) page.evaluate("history.length")).intValue();
+
+        queryLog.clear();
+        nameInput.click();
+        nameInput.pressSequentially("Aaltonen", new Locator.PressSequentiallyOptions().setDelay(30));
+
+        // Give the LAZY debounce time to settle and the server round trip to land.
+        page.waitForTimeout(800);
+
+        int pageQueries = queryLog.pageQueries().size();
+        int countQueries = queryLog.countQueries().size();
+        assertTrue(pageQueries <= 2, "Typing 9 letters cost " + pageQueries + " page queries, expected 1-2");
+        assertTrue(countQueries <= 2, "Typing 9 letters cost " + countQueries + " count queries, expected 1-2");
+        assertTrue(pageQueries >= 1, "Typing must eventually query the backend");
+
+        assertTrue(page.url().contains("name=Aaltonen"), "URL should carry the name filter: " + page.url());
+
+        int historyLengthAfter = ((Number) page.evaluate("history.length")).intValue();
+        assertEquals(historyLengthBefore, historyLengthAfter,
+                "Filtering must use replaceState, not push a new history entry per keystroke");
+    }
+
+    @Test
+    void clearingTheNameFilterRemovesItFromTheUrl() {
+        Page page = getPage();
+        Locator nameInput = nameInputLocator(page);
+
+        nameInput.click();
+        nameInput.pressSequentially("vir", new Locator.PressSequentiallyOptions().setDelay(30));
+        page.waitForTimeout(700);
+        assertTrue(page.url().contains("name=vir"), "URL should carry the name filter: " + page.url());
+
+        nameInput.fill("");
+        page.waitForTimeout(700);
+        assertFalse(page.url().contains("name="), "Clearing the filter should remove it from the URL: " + page.url());
+    }
+
+    @Test
+    void selectingAStatusUpdatesTheUrlWithDeclarationOrder() {
+        Page page = getPage();
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusFilter.selectItem("CLOSED");
+        statusFilter.selectItem("ACTIVE");
+        page.waitForTimeout(500);
+
+        assertTrue(page.url().contains("status=ACTIVE%2CCLOSED") || page.url().contains("status=ACTIVE,CLOSED"),
+                "Statuses should appear in declaration order regardless of selection order: " + page.url());
+    }
+
+    @Test
+    void openingAUrlWithParametersRendersTheFilteredState() {
+        Page page = getPage();
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE");
+        page.waitForSelector("vaadin-grid");
+        page.waitForTimeout(500);
+
+        Locator nameInput = nameInputLocator(page);
+        assertEquals("vir", nameInput.inputValue());
+
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statusFilter.assertSelectedItems("ACTIVE");
+    }
+}
