+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.text.Normalizer;
+import java.util.ArrayList;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+/**
+ * Exercises {@link CustomerRepository}'s filtering directly, against an
+ * independently written reference oracle, rather than through the UI.
+ */
+class CustomerFilterMatchingTest {
+
+    private CustomerRepository repository;
+    private List<Customer> allCustomers;
+
+    @BeforeEach
+    void setUp() {
+        repository = new CustomerRepository(new QueryLog());
+        allCustomers = new ArrayList<>();
+        int offset = 0;
+        int total = repository.count(CustomerFilter.EMPTY);
+        while (offset < total) {
+            List<Customer> page = repository.findAll(offset, CustomerRepository.MAX_PAGE_SIZE,
+                    List.of(), CustomerFilter.EMPTY);
+            allCustomers.addAll(page);
+            offset += page.size();
+        }
+        assertEquals(total, allCustomers.size());
+    }
+
+    /** Reference implementation of the matching rule, written independently of the repository. */
+    private List<Customer> expectedMatches(String name, Set<CustomerStatus> statuses) {
+        List<String> terms = name.isBlank() ? List.of()
+                : Arrays.stream(name.trim().split("\\s+")).map(this::fold).toList();
+        return allCustomers.stream()
+                .filter(c -> statuses.isEmpty() || statuses.contains(c.status()))
+                .filter(c -> terms.stream().allMatch(term ->
+                        fold(c.firstName()).contains(term) || fold(c.lastName()).contains(term)))
+                .toList();
+    }
+
+    private String fold(String s) {
+        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
+        return Pattern.compile("\\p{M}").matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+
+    private List<Customer> matches(String name, Set<CustomerStatus> statuses) {
+        CustomerFilter filter = new CustomerFilter(name, statuses);
+        return repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE, List.of(), filter);
+    }
+
+    private int count(String name, Set<CustomerStatus> statuses) {
+        return repository.count(new CustomerFilter(name, statuses));
+    }
+
+    @Test
+    void emptyFilterMatchesEveryCustomer() {
+        assertEquals(allCustomers.size(), count("", Set.of()));
+    }
+
+    @Test
+    void bothOrdersOfTwoTermsMatchTheSameCustomers() {
+        List<Customer> forward = matches("ada aal", Set.of());
+        List<Customer> backward = matches("aal ada", Set.of());
+        assertEquals(expectedIds("ada aal"), idsOf(forward));
+        assertEquals(idsOf(forward), idsOf(backward));
+        assertFalse(forward.isEmpty());
+        forward.forEach(c -> {
+            assertTrue(fold(c.firstName()).contains("ada") || fold(c.lastName()).contains("ada"));
+            assertTrue(fold(c.firstName()).contains("aal") || fold(c.lastName()).contains("aal"));
+        });
+    }
+
+    @Test
+    void unrelatedTermsMatchNobody() {
+        assertEquals(0, count("ada virtanen", Set.of()));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccents() {
+        int lower = count("makinen", Set.of());
+        int upper = count("MAKINEN", Set.of());
+        int accented = count("mäkinen", Set.of());
+        assertTrue(lower > 0);
+        assertEquals(lower, upper);
+        assertEquals(lower, accented);
+        assertEquals(expectedIds("makinen"), idsOf(matches("MAKINEN", Set.of())));
+    }
+
+    @Test
+    void matchingIgnoresAccentsInBothDirections() {
+        int plain = count("josephine", Set.of());
+        int accented = count("joséphine", Set.of());
+        assertTrue(plain > 0);
+        assertEquals(plain, accented);
+        assertEquals(expectedIds("josephine"), idsOf(matches("josephine", Set.of())));
+    }
+
+    @Test
